import java.util.*;

class Solution {
    public int maxDistance(int[] position, int m) {
        Arrays.sort(position);
        int lo = 1, hi = position[position.length - 1] - position[0];
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;       // upper mid: lo moves up
            if (canPlace(position, m, mid)) lo = mid; // gap mid works, try bigger
            else hi = mid - 1;
        }
        return lo;
    }

    private boolean canPlace(int[] pos, int m, int gap) {
        int count = 1, last = pos[0];               // first beacon on the first spot
        for (int i = 1; i < pos.length; i++) {
            if (pos[i] - last >= gap) { count++; last = pos[i]; }
            if (count >= m) return true;
        }
        return false;
    }
}

