class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        p = sorted(position)
        def fits(g):
            cnt, last = 1, p[0]
            for x in p[1:]:
                if x - last >= g: cnt, last = cnt + 1, x
            return cnt >= m
        lo, hi = 1, p[-1] - p[0]
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if fits(mid): lo = mid
            else: hi = mid - 1
        return lo

