function maxDistance(position, m) {
  const p = [...position].sort((a, b) => a - b);
  const fits = (g) => { let c = 1, last = p[0]; for (let i = 1; i < p.length; i++) if (p[i] - last >= g) { c++; last = p[i]; } return c >= m; };
  let best = 1, lo = 1, hi = p[p.length - 1] - p[0];
  while (lo <= hi) { const mid = Math.floor((lo + hi) / 2); if (fits(mid)) { best = mid; lo = mid + 1; } else hi = mid - 1; }
  return best;
}
